head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > sortOrderReverse]<br/>sortable=true 인 Header Column 의 데이터 정렬 시 우선 적용되는 정렬 방식을 설정합니다.",
    "validation" : [
        "true 설정 시 Header Column 클릭으로 정렬 시 내림차순(Descending) > 오름차순(Ascending) > 정렬해제(Unsorted) 순서로 순환합니다.",
        "false(기본값) 설정 시 Header Column 클릭으로 정렬 시 오름차순(Ascending) > 내림차순(Descending) > 정렬해제(Unsorted) 순서로 순환합니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 읽기 (미설정 '' / 'true' / 'false')
    let sortOrderReverseVal = con_sortOrderReverse.getValue();

    // 현재 설정/동작 라벨 생성 (target 생성 전 가장 먼저 생성)
    //  부등호( < > ) 금지 → 유니코드 화살표(→) 로 순환 표기
    $c.gcm.createLabel('label="Header Column 을 클릭하면 데이터가 정렬됩니다. (sortable=true, sortEvent=onclick, showSortableImage=true 고정) / 초기 표시순서: Cherry, Apple, Date, Banana"', '', 'label1');
    $c.gcm.createLabel('label="현재 설정: sortOrderReverse=' + (sortOrderReverseVal === '' ? '미설정(기본 false)' : sortOrderReverseVal) + ' / 클릭 순환: ' + (sortOrderReverseVal === 'true' ? '내림차순 → 오름차순 → 정렬해제' : '오름차순 → 내림차순 → 정렬해제') + '"', '', 'label2');

    // dataList 직접 생성 (4행, 빈 행 0 / 정렬 시 순서가 눈에 띄게 바뀌도록 비정렬 배치)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    let nameArr = ['Cherry', 'Apple', 'Date', 'Banana'];
    let descArr = ['체리', '사과', '대추', '바나나'];
    for (let r = 0; r < 4; r++) {
        strDl += '<w2:row>';
        strDl += '<col1>' + nameArr[r] + '</col1>';
        strDl += '<col2>' + descArr[r] + '</col2>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // sortOrderReverse 속성 (미설정 시 속성 미부여 = 기본값 false)
    let sortOrderReverseAttr = sortOrderReverseVal === '' ? '' : 'sortOrderReverse="' + sortOrderReverseVal + '" ';

    // target 생성 : sortable=true / sortEvent=onclick / showSortableImage=true 고정, sortOrderReverse 조건 적용
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + sortOrderReverseAttr + 'sortable="true" sortEvent="onclick" showSortableImage="true" dataList="data:dlt_bind" checkAllType="false" id="" ev:onsort="scwin.target1_onsort" style="width:420px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="column2" value="desc"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" inputType="text" dataType="text" id="col1"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" dataType="text" id="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 정렬 실행(onsort) 시 자동 출력 : 정렬 방향(오름/내림/해제) + 정렬 후 name 컬럼 표시순서
//  (헤더 클릭은 사용자 액션으로 수행 → 정렬 트리거 버튼은 생성하지 않음)
//  onsort 는 sortable 적용 헤더에서 클릭으로 정렬방식이 변경되었을 때 발생하므로,
//  매 클릭마다 sortOrderReverse 순환 단계(내림/오름/해제)를 관찰할 수 있다.
scwin.target1_onsort = function () {
    // 정렬 후 화면에 보이는 name(col1) 컬럼 데이터를 표시순서대로 수집
    let order = [];
    let bodyTable = document.querySelector("[id*='target1_body_table']");
    if (bodyTable) {
        // 첫번째 데이터 컬럼(col1) 셀만 행 순서대로 추출
        let nameCells = bodyTable.querySelectorAll("td[id*='_cell_'][id$='_0']");
        for (let i = 0; i < nameCells.length; i++) {
            let t = (nameCells[i].textContent || "").trim();
            if (t) {
                order.push(t);
            }
        }
    }

    // 현재 정렬 방향 : name 헤더 th 의 aria-sort 로 판별 (ascending/descending/none)
    //  aria-sort=none 또는 부재 → 정렬해제(원래 데이터 순서 복귀)
    let dir = "정렬해제";
    let headTable = document.querySelector("[id*='target1_head_table']");
    if (headTable) {
        let th = headTable.querySelector("th[aria-sort='ascending'], th[aria-sort='descending']");
        if (th) {
            dir = th.getAttribute("aria-sort") === "ascending" ? "오름차순" : "내림차순";
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("[정렬 실행] 컬럼=name / 방향=" + dir + " / 표시순서=" + order.join(", "));
};
